function field(id: string, title: string, purpose: string, scope: string, change: string, options: FieldOptions = {}): Readonly<AppConfigurationGuideField> {
  return Object.freeze({ id, title, purpose, scope, read: "Leia o estado exibido nesta tela da base conectada. Este manual não consulta o estado nem contém dados do proprietário.",
    change, approval: uiApproval, result: "Confirme o estado ou receipt retornado. Rascunho, clique ou documentação não prova aplicação nem execução.", recovery, availability: "ui_only", readOperation: null, changeOperation: null, ...options });
}
function proposal(id: string, title: string, purpose: string, scope: string, change: string, operation: string, options: FieldOptions = {}): Readonly<AppConfigurationGuideField> {
  const executable = ["dexter.harness.terminal.run", "dexter.harness.cli.run", "dexter.harness.files.write", "dexter.browseruse.run", "dexter.automations.run"].includes(operation);
  return field(id, title, purpose, scope, change, { approval: ["dexter.harness.documents.update", "dexter.harness.memory.append"].includes(operation) ? ownDocumentApproval : executable ? executionApproval : proposalApproval, availability: "harness_when_exposed", changeOperation: operation, ...options });
}
function local(id: string, title: string, purpose: string, scope: string, change: string, options: FieldOptions = {}): Readonly<AppConfigurationGuideField> {
  return field(id, title, purpose, scope, change, { approval: "Navegação ou rascunho local, sem concessão ou mutação administrativa. O bot não possui handler para comandar a UI por este manual.", ...options });
}
function readonly(id: string, title: string, purpose: string, scope: string, read: string, options: FieldOptions = {}): Readonly<AppConfigurationGuideField> {
  return field(id, title, purpose, scope, "Sem alteração por este controle.", { availability: "read_only", read,
    approval: "Leitura não concede escrita, acesso a outros bots ou prova de funcionamento.", ...options });
}


