/** UI delivery overlays applied after consumer aliases exist. Static documentation; no IO or authority. */
function applyDeliveryUIGuideOverlays(inputs: readonly PageInput[]): readonly PageInput[] {
  return inputs.map(input => {
    const fields = new Map(input.fields.map(f => [f.id, f]));
    const notes = input.notes.map(n => n.startsWith("Arquivos: o backend e o SDK de saídas")
      ? "Perfil › Arquivos mostra a pasta deste bot na base desta janela: Ver arquivos… filtrado e Mostrar no Finder só na base deste Mac; a pasta geral escolhida aparece em Ajustes › Geral. Destino novo vale só para arquivos novos: nada é movido ou apagado. A pasta do bot não é sandbox do sistema. VPS offline nunca permite trocar pela pasta deste Mac."
      : n);
    const add = (entries: readonly Readonly<AppConfigurationGuideField>[]) => {
      for (const f of entries) { if (fields.has(f.id)) throw new Error(`Delivery guide duplicate: ${input.id}/${f.id}`); fields.set(f.id, f); }
    };
    const update = (id: string, values: Partial<AppConfigurationGuideField>) => {
      const prior = fields.get(id); if (!prior) throw new Error(`Delivery guide missing: ${input.id}/${id}`);
      fields.set(id, Object.freeze({...prior,...values}));
    };
    const sources = [...input.sourcePaths];
    if (input.id === "settings-general") { add(filesUiGeneralFields); sources.push(view("OutputFilesViews")); }
    if (input.id === "output-files") {
      add(filesUiBrowserFields); sources.push(view("OutputFilesViews"), "apps/apple/Sources/DexterAppCore/OutputFilesSession.swift");
      for (const [id, text] of Object.entries(outputFilesUiLocations)) {
        const prior = fields.get(id); if (!prior) throw new Error(`Output guide missing ${id}`);
        update(id, {change: `${prior.change} ${text}`});
      }
      notes.push("A UI lista Geral/Bots/Times, pastas atuais e anteriores, subpastas e paginação. Troca de pasta pede confirmação/CAS/receipt e só muda arquivos novos. Base remota oferece Baixar; Finder só na base deste Mac. Resultado incerto usa Conferir por GET, sem reenvio exposto. Composição compilada e testes sintéticos não provam relay/VPS ou download pela GUI.");
    }
    if (input.id === "bot-settings") {
      add(filesUiBotFields);
      update("bot-profile.files", {purpose: "Ver arquivos deste bot e a localização geral dos arquivos novos.", scope: "bot fixo da janela × base capturada",
        read: filesUiRead, change: "Perfil › Arquivos: bot-profile.files.open abre files.sheet filtrada em bot:<id>; bot-profile.files.reveal só na base deste Mac. Pasta geral é somente leitura; altere em Ajustes › Geral › Arquivos gerados.",
        approval: "Navegação humana não altera arquivos nem concede grants.", result: "Lista real do namespace deste bot, incluindo gerações anteriores; outro bot/Time/Grupo não é adotado.",
        recovery: "Outra base, offline ou escopo ausente: aviso honesto; nunca trocar pela base deste Mac.", availability: "ui_only", readOperation: "GET /v1/output-files/namespaces", changeOperation: null});
      sources.push(view("OutputFilesViews"));
    }
    if (input.id === "team-editor") { add(filesUiTeamFields); sources.push(view("OutputFilesViews")); }
    if (input.id === "settings-connections" || input.id === "settings-integrations") {
      add(connectAppsUiFields); sources.push(view("ManagedConnectAppsViews"), "apps/apple/Sources/DexterAppCore/ManagedConnectAppsEditor.swift");
      add(connectAppsPlatformUiFields); sources.push(view("ConnectionsPlatformSetupViews"));
      update("services-catalog", {purpose: "Referência estável do catálogo de apps; agora use connect-apps-catalog.",
        read: connectAppsRead, change: "Conectar apps usa as linhas settings.connections.service.<id> quando platform=available. Sem serviço configurado, mostra unconfigured com explicação; o antigo controle catalog-unavailable não existe mais.",
        availability: "read_only", readOperation: "GET /v1/connections/status, /catalog", changeOperation: null});
      notes.push(CONNECT_APPS_PLATFORM_UI_NOTE);
    }
    if (input.id === "settings-this-mac" || input.id === "settings-devices") {
      add(ownerOfferUiEntryFields); add(ownerClaimsUiEntryFields); sources.push(view("OwnerPairingOfferViews"), view("OwnerPairingClaimsViews"));
    }
    if (input.id === "owner-pairing-offer") {
      add(ownerOfferUiApprovalFields); sources.push(view("OwnerPairingOfferViews"), "apps/apple/Sources/DexterAppCore/OwnerPairingOfferSession.swift");
      notes[0] = "A folha privada está composta na fonte consolidada da entrega local build11: Ajustes › Este Mac › Conectar aparelhos › Convidar outro aparelho…. Instalar o app não configura o canal seguro. Status real unavailable/app_client_channel_unconfigured mantém Criar desabilitado; a UI não cria TLS, chave ou certificado. Convite não concede grants a bots; aprovação do pedido é um passo separado no app. Esta consolidação não prova convite emitido, novo pareamento ou identidade física criada.";
      notes.push("O app nunca desenha o texto do convite. Copiar coloca-o na área de transferência com marcador sensível; Esconder/fechar retira-o da memória. Copiar foi compilado e revisado, não exercido na GUI. Aprovar/recusar o aparelho é feito no app: Revisar pedido… (owner-pairing-offer.review-request) abre Pedidos de aparelhos no pedido deste convite; nenhum terminal.");
      for (const [id,text] of Object.entries(ownerOfferUiLocations)) { const prior=fields.get(id); if (!prior) throw new Error(`Offer guide missing ${id}`); update(id,{change: `${prior.change} ${text}`}); }
      update("owner-pairing-offer.create", {recovery: `${fields.get("owner-pairing-offer.create")!.recovery} ${ownerOfferConflictUi}`});
    }
    if (input.id === "owner-pairing-claims") {
      add(ownerClaimsUiExtraFields);
      sources.push(view("OwnerPairingClaimsViews"), "apps/apple/Sources/DexterAppCore/OwnerPairingClaimsSession.swift");
      notes[0] = "A folha privada está composta na fonte consolidada da entrega local build11: Ajustes › Este Mac › Conectar aparelhos › Pedidos de aparelhos… (e Revisar pedido… no convite usado). Status real unavailable/app_client_channel_unconfigured: a folha explica o motivo e nenhuma decisão é possível; a UI não cria TLS, chave nem Keychain. Substitui `dexter app-client claims/approve/reject` quando o canal existir. Esta consolidação não prova aprovação real de aparelho ou novo vínculo.";
      for (const [id,text] of Object.entries(ownerClaimsUiLocations)) { const prior=fields.get(id); if (!prior) throw new Error(`Claims guide missing ${id}`); update(id,{change: `${prior.change} ${text}`}); }
    }
    if (input.id === "chat-live" || input.id === "native-codex-voice") {
      notes.push("Plataforma: chamadas de voz Codex nativas e Live por API desta implementação têm mídia somente no Mac. No iPhone, canStartLiveVoice=false e iniciar informa indisponível, sem criar sessão, acessar rede ou pedir microfone. Compilar o app iOS não comprova chamada de voz. A captura curta da tela de capacidades do aparelho possui seu próprio fluxo e consentimento.");
      sources.push("apps/apple/Sources/DexterAppCore/DexterAppModel.swift");
    }
    if (input.id === "paired-host") {
      add([connectOtherBaseVerificationField]); sources.push(view("ConnectOtherBaseSheet"), view("SettingsView"));
      update("pairing-offer.scopes", {availability: "human_only", read: "Na base deste Mac, GET /v1/owner/app-client-pairing/status: estado e limites reais. Canal unconfigured não permite criar convite.",
        change: "Ajustes › Este Mac › Conectar aparelhos › Convidar outro aparelho…: tipo iPhone/Mac explícito e outputs.read/manage por gesto. Consulte owner-pairing-offer; a UI não fabrica oferta local nem usa dados da base remota como convite.",
        result: "Somente convite real confirmado pela base de origem; nenhum grant de bot.", recovery: ownerPairingRecovery,
        readOperation: "GET owner-local /v1/owner/app-client-pairing/status", changeOperation: "POST owner-local /v1/owner/app-client-pairing/offers (gesto humano)"});
    }
    return {...input, fields:[...fields.values()], notes, sourcePaths:[...new Set(sources)]};
  });
}


const platformConfigurationRecovery = "Resultado incerto ao salvar (mutationOutcomeUnknown/503) preserva o pedido original: GET /v1/connections/platform-configuration/receipts/:clientRequestId com o MESMO id; 404 = não confirmado, nunca \"não aconteceu\". Mesmo id + mesmo corpo devolve o receipt original; mesmo id com outro corpo = 409. 409 de revisão: consulte o estado antes de salvar de novo. Origem presa a outras conexões (409): desconecte/remova as contas da origem anterior antes de trocar.";
const platformCredentialRecovery = "Confirmação privada perdida: o app mantém o pedido e consulta GET /v1/connections/platform-configuration (privateRequest com o MESMO requestId, operação e geração); a credencial nunca é reenviada automaticamente. refused: confira se o host foi reiniciado com esta origem/geração. Credencial errada/revogada no serviço: gere nova geração (renovar) e informe a nova; a antiga deixa de ser aceita.";

const CONNECTIONS_MANAGED_ROUTE_NOTE = "Rota gerenciada: o host fala com o serviço de conexões confiável que o proprietário opera (ConnectionsPlatformService, origem HTTPS informada por ele; não existe URL de nuvem do Dexter), que guarda a chave de projeto do fornecedor; o host usa só uma capability limitada da instalação, emitida pelo operador desse serviço. Fornecedor atual com adapter: Composio (REST v3.1). Pipedream e Nango são candidatos sem adapter e não aparecem. O `dexter serve` lançado pelo app compõe o serviço SÓ a partir da configuração privada do proprietário (connections.platform-configuration) depois de reiniciar, com MCP e engines ativos e o canal privado do app; a capability chega só pelo pipe privado (connections.platform-credential). Sem isso, status.platform = unconfigured (ou unavailable sem a credencial) e o catálogo fica vazio. Salvar não é conectar.";

