const audienceBoundary = "Fronteira de audiência M01: conversa privada usa documentos/skills próprios e páginas owner-global explicitamente compartilhadas; pertencer a Times não abre seus conteúdos no privado. Turno de Time consulta somente o Time atual e suas skills ativas; não recebe SOUL/USER/MEMORY privados, páginas owner-global, compartimentos confidenciais ou outro Time. Documentos/histórico/receipts e rotinas privadas não são ferramentas de um turno de Time. Artefatos privados do bot não entram implicitamente no Time. Janelas owner de Ajustes continuam podendo administrar a memória privada do coordenador; isso não publica seu texto na conversa do Time.";
const audienceRecovery = "Se um acesso privado está ausente no turno de Time, mantenha o escopo: não peça outro bot/ID, não use cursor antigo nem reenvie por outra ferramenta. Abra uma conversa privada para o recurso privado. Publicação aprovada de memória/skills em novo escopo pertence à etapa M06 e ainda não tem handler nesta parcela. Rebind de conversa com histórico privado é recusado; crie uma conversa nova de Time. Revogação durante recall descarta o resultado tardio.";

function freezePage(input: PageInput): Readonly<AppConfigurationGuidePage> {
  const readiness = ENGINE_READINESS_GUIDE_OVERLAYS.find(value => value.pageID === (input.id==='settings-assistants'?'settings-models':input.id));
  if (readiness) input = { ...input, sourcePaths: [...input.sourcePaths, ...ENGINE_READINESS_GUIDE_SOURCE_PATHS],
    notes: [...input.notes, 'Consulta atual e erro são fatos de leitura; indisponibilidade de native voice não implica ausência da engine para chat. Nenhuma leitura muda CLI/conta/default ou autoriza inferência.'],
    fields: input.fields.map(value => Object.freeze({ ...value, ...readiness.fields[value.id] })) };
  const pageVersion=input.id==="native-keychain-signing"?"1.3.1":input.id===MEMORY_LEARNING_CONFIGURATION_PAGE.id?MEMORY_LEARNING_CONFIGURATION_PAGE.version:input.id===NATIVE_VOICE_PAGE_INPUT.id?NATIVE_VOICE_GUIDE_VERSION:input.id===GROUP_CONFIGURATION_PAGE_INPUT.id?GROUP_CONFIGURATION_GUIDE_VERSION:readiness?`${APP_CONFIGURATION_GUIDE_VERSION}+${ENGINE_READINESS_GUIDE_REVISION}`:APP_CONFIGURATION_GUIDE_VERSION;
  if (audiencePages.has(input.id)) input = { ...input,
    sourcePaths: [...input.sourcePaths,"packages/context/src/memory-policy.ts"],
    notes: [...input.notes,audienceBoundary,audienceRecovery],
    fields: input.fields.map(value => Object.freeze({ ...value, scope: `${value.scope}; audiência derivada do host, não selecionada por input da engine`,
      read: `${value.read} Ferramentas privadas não ficam disponíveis em turno de Time; a UI owner conserva leitura privada.`, change: `${value.change} Um controle privado só é exposto no turno privado; a UI owner mantém seu fluxo de aprovação existente.`,
      result: `${value.result} A edição privada não publica em Time; captura literal de Time é recusada como nota privada.`,
      recovery: `${value.recovery} Acesso ausente por audiência não é falha transitória: use conversa privada ou publicação explícita quando implementada.` })) };

  const sourcePaths = Object.freeze([...input.sourcePaths]);
  const notes = Object.freeze([...input.notes]);
  const fields = Object.freeze([...input.fields]);
  const markdown = `# ${input.title}\n\nID: ${input.id}\nVersão: ${pageVersion}\nEscopo: ${input.scope}\nDisponibilidade: ${input.availability}\n\nEste é um manual first-party code-owned. Não contém estado pessoal, não faz probes e não concede acesso. Uma operação só é chamável com alias/schema no tools/list. ui_only/human_only exige o fluxo apropriado; terminal/arquivos não contornam grants, secrets, OAuth, pairing, TCC ou decisão humana. Ferramentas first-party expostas servem a tarefas legítimas no próprio escopo e com aprovação exigida.\n\n## Fontes de implementação\n${sourcePaths.map(path => `- ${path}`).join("\n")}\n\n## Limites desta página\n${notes.map(note => `- ${note}`).join("\n")}\n\n${fields.map(value => `## ${value.title}\nID do controle: ${value.id}\n- Propósito: ${value.purpose}\n- Escopo: ${value.scope}\n- Ler: ${value.read}\n- Alterar: ${value.change}\n- Aprovação: ${value.approval}\n- Resultado: ${value.result}\n- Recuperação: ${value.recovery}\n- Disponibilidade: ${value.availability}\n- Operação de leitura: ${value.readOperation ?? "não exposta por esta documentação"}\n- Operação de alteração: ${value.changeOperation ?? "não exposta; UI/humano ou indisponível conforme acima"}\n`).join("\n")}`;
  return Object.freeze({ ...input, sourcePaths, notes, fields, version: pageVersion,
    sha256: createHash("sha256").update(markdown, "utf8").digest("hex"), characters: markdown.length, markdown });
}
