function applyLayoutGuideOverlay(input: PageInput): PageInput {
  const overlay = layoutGuideOverlay.find(page => page.pageId === input.id);
  if (!overlay) return input;
  const fields = new Map(input.fields.map(value => [value.id,value]));
  for (const value of overlay.fieldsUpsert) fields.set(value.id,Object.freeze({ ...value }));
  return { ...input, sourcePaths: [...new Set([...input.sourcePaths,...(overlay.sourcePathsAdd ?? [])])],
    notes: [...input.notes,...(overlay.notesAdd ?? [])], fields: [...fields.values()] };
}
function applyCompletionGuideOverlay(input:PageInput):PageInput {
  const fields=new Map(input.fields.map(value=>[value.id,value]));
  for(const overlay of COMPLETION_UI_FIELD_OVERLAYS)if(overlay.pageId===input.id) {
    const previous=fields.get(overlay.field.id);
    fields.set(overlay.field.id,Object.freeze({...overlay.field,
      ...(previous?.changeOperation ? {change:overlay.field.change+" Detalhes do host: "+previous.change,availability:previous.availability,changeOperation:previous.changeOperation,readOperation:previous.readOperation} : {})}));
  }
  return {...input,fields:[...fields.values()]};
}
const pages: readonly Readonly<AppConfigurationGuidePage>[] = Object.freeze(applyDeliveryUIGuideOverlays(applyConsumerUIGuideOverlays([...inputs,memoryServicePage,MEMORY_RECALL_GUIDE_PAGE_INPUT,MEMORY_LEARNING_CONFIGURATION_PAGE,deviceRoutesGuidePage,...COMPLETION_ADDITIONAL_PAGES,...MCP_COMPLETE_GUIDE_PAGES,ASSISTANT_FIRST_RUN_GUIDE_PAGE_INPUT,BOT_ACTIVITY_GUIDE_PAGE_INPUT,IOS_QR_PAIRING_GUIDE_PAGE_INPUT].map(applyLayoutGuideOverlay).map(applyCompletionGuideOverlay))).map(applyMcpCompleteGuideOverlay).map(augmentMcpAppleControls).map(applyAssistantFirstRunGuideOverlay).map(applyAudioMacPreparationGuideOverlay).map(applyIOSQRPairingGuideOverlay).map(freezePage));
/** Index for progressive loading. All nested values are frozen and contain static documentation only. */
export const APP_CONFIGURATION_GUIDE_PAGES: readonly Readonly<AppConfigurationGuidePageSummary>[] = Object.freeze(pages.map(page => Object.freeze({
  id: page.id, title: page.title, version: page.version, sha256: page.sha256, characters: page.characters,
  scope: page.scope, availability: page.availability,
  fields: Object.freeze(page.fields.map(value => Object.freeze({ id: value.id, title: value.title, scope: value.scope,
    availability: value.availability, readOperation: value.readOperation, changeOperation: value.changeOperation }))),
})));
/** No IO, registry lookup, personal data, credentials, native cursor or executable discovery. */
export function readAppConfigurationGuidePage(pageId: string): Readonly<AppConfigurationGuidePage> {
  const page = pages.find(value => value.id === pageId);
  if (!page) throw new ContextError("not_found", "Built-in app configuration guide page not found.");
  return page;
}
